\section{Supplementary Material}

To evaluate the behaviour of the solution to the photon equation of motion, we start with a form similar to Eq.~(A4) of \cite{Fedderke:2019ajk},
\begin{equation}
    \left( \frac{\partial^2}{\partial t^2} - \Delta \right) \vec{A} = 
    \pm i g_{a\gamma} \left[ \left( \partial_z a \right) \partial_t \vec{A} - \left( \partial_t a \right) \partial_z \vec{A} \right].
\end{equation}
Let us transform to $u-v$ coordinates: $u=z-t$ and $v=z+t$ $\Rightarrow$ $z=\frac{1}{2}(u+v)$; $z=\frac{1}{2}(v-u)$ 
\begin{equation}
    \Rightarrow \quad 
    \frac{\!\!\!\partial}{\partial z} = \frac{\!\!\!\partial}{\partial u} + \frac{\!\!\!\partial}{\partial v}\,; 
    \quad
    \frac{\!\!\partial}{\partial t} = -\frac{\!\!\!\partial}{\partial u} + \frac{\!\!\!\partial}{\partial v}\,;
\end{equation}
\begin{equation}
    \Rightarrow \quad 
    \frac{\partial a}{\partial z} \frac{\partial A}{\partial t} - 
    \frac{\partial a}{\partial t} \frac{\partial A}{\partial z} 
    = 
    \left(\frac{\partial a}{\partial v} + \frac{\partial a}{\partial u}\right) 
    \left(\frac{\partial A}{\partial v} - \frac{\partial A}{\partial u}\right) 
    -
    \left(\frac{\partial a}{\partial v} - \frac{\partial a}{\partial u}\right) 
    \left(\frac{\partial A}{\partial v} + \frac{\partial A}{\partial u}\right) 
    =
    -2 \frac{\partial a}{\partial v} \frac{\partial A}{\partial u} 
    +2 \frac{\partial a}{\partial u} \frac{\partial A}{\partial v}.
\end{equation}
The boundary condition at $v_{\rm max}$ is $\partial A / \partial v=0$; we define $\phi_a \mathrel{\mathop:}= g_{a\gamma}a / 2$
\begin{equation}\label{eq:star}
    \Rightarrow \quad 
    - \frac{\!\!\!\partial}{\partial u} \frac{\!\!\!\partial}{\partial v} A =
    \pm i \left(  \frac{\partial \phi_a}{\partial u} \frac{\partial A}{\partial v} - 
    \frac{\partial \phi_a}{\partial v} \frac{\partial A}{\partial u} \right).
\end{equation}
Now, we make the ansatz $A(u,v) = f(u) e^{\pm i \phi} + g(v) e^{\mp i \phi}$
\begin{equation}
    \Rightarrow \quad \frac{\partial A}{\partial u}  = \pm i \frac{\partial \phi}{\partial v} f(u) e^{\pm i \phi}
    + g' e^{\mp i \phi} \mp i \frac{\partial \phi}{\partial v} g(v) e^{\mp i \phi},
\end{equation}
\begin{equation}
    \Rightarrow \quad \frac{\partial^2 A}{\partial u\partial v}  = \pm i \frac{\partial^2 \phi}{\partial u\partial v} f(u) e^{\pm i \phi}
    \pm i \frac{\partial \phi}{\partial v} f' e^{\pm i \phi}
    \mp i \frac{\partial \phi}{\partial u} g' e^{\mp i \phi} 
    \mp i \frac{\partial^2 \phi}{\partial u\partial v} g(v) e^{\mp i \phi}
    -  \frac{\partial \phi}{\partial v} \frac{\partial \phi}{\partial u} A.
\end{equation}
We note that 
\begin{equation}
    \frac{\partial \phi}{\partial u} , \frac{\partial \phi}{\partial v} \sim \mathcal{O}(m_a)\phi\,; 
    \quad  \frac{\partial^2 \phi}{\partial u\partial v} \sim \mathcal{O}(m_a^2)\phi\,; \quad f', g' \sim \mathcal{O}(k)(f,g).
\end{equation}
Then the R.H.S. of Eq.~(\ref{eq:star}) is 
\begin{equation}
\pm i \left(  \frac{\partial \phi_a}{\partial u} g' e^{\mp i \phi} - 
      \frac{\partial \phi_a}{\partial v} f' e^{\pm i \phi} \right) 
    - \frac{\partial \phi_a}{\partial u} \frac{\partial \phi}{\partial v} f e^{\pm i \phi}
    + \frac{\partial \phi_a}{\partial u} \frac{\partial \phi}{\partial v} g e^{\mp i \phi}
    + \frac{\partial \phi_a}{\partial v} \frac{\partial \phi}{\partial u} f e^{\pm i \phi}
    - \frac{\partial \phi_a}{\partial v} \frac{\partial \phi}{\partial u} g e^{\mp i \phi}
\end{equation}
which implies that the non-linear terms do not cancel but are suppressed by $(m_a/k)$ relative to the other terms.\\
\\
If $m_a \ll k$, then to first order in $\phi$ the L.H.S. of Eq.~(\ref{eq:star}) is 
\begin{equation}
\pm i \frac{\partial \phi_a}{\partial u} g' e^{\mp i \phi} 
\mp i \frac{\partial \phi_a}{\partial v} f' e^{\pm i \phi},
\end{equation}
to first order in $\phi$, $\phi_a$ one thus has,
\begin{equation}
      \frac{\partial^2 \phi}{\partial u\partial v} f(u) 
    + \frac{\partial \phi}{\partial v} f'(u)
    = \frac{\partial \phi_a}{\partial v} f'(u),
\end{equation}
\begin{equation}
      \frac{\partial^2 \phi}{\partial u\partial v} g(v) 
    + \frac{\partial \phi}{\partial u} g'(v)
    = \frac{\partial \phi_a}{\partial u} g'(v).
\end{equation}
For $f(u) \propto e^{i k u}$ one has $f'(u)=ikf(u)$,
\begin{equation}
     \Rightarrow \quad 
     \frac{\partial^2 \phi}{\partial u\partial v} 
    + ik \left( \frac{\partial \phi}{\partial v}
    - \frac{\partial \phi_a}{\partial v} \right) = 0,
\end{equation}
whose general solution is
\begin{equation}\label{eq:phi_sol}
    \phi(u,v) = ik\int^u\phi_a(u',v) e^{ik\left( u'-u \right)} du' +c(v)e^{-iku}.
\end{equation}
Further, because 
\begin{equation}
    \frac{\partial \phi}{\partial u} = ik \phi_a(u,v) - ik \phi(u,v),
\end{equation}
\begin{equation}
     \Rightarrow \quad 
     \frac{\partial^2 \phi}{\partial v\partial u} 
    = ik \left( \frac{\partial \phi_a}{\partial v}
    - \frac{\partial \phi}{\partial v} \right).
\end{equation}
The boundary conditions, in general, eliminate the homogeneous term $\propto c(v)$. If $\phi_a$ varies very slowly, it can be pulled out in front of the integral in Eq.~(\ref{eq:phi_sol}) so that, 
\begin{equation}
    \phi(u,v) \sim \phi_a(u,v)
\end{equation}
for the case $m_a \ll k$. This is equivalent to neglecting second derivatives of the photon phase $\phi$. 

We conclude that for CMB birefringence due to ALPs, where $g_{a\gamma}$ constraints can be improved over the range $10^{-27} \lesssim m_a \lesssim 10^{-24}$ eV, the fact that $m_a \ll k$ implies that non-linear terms are highly suppressed and we can use $\phi \sim g_{a\gamma} a /2$ or Eq.\,(4), $\Delta \phi \sim g_{a\gamma} \Delta a$. 
The ratio $(m_a/k) \sim 1$ for much larger ALP masses $m_a \sim 10^{-6}$ eV where non-linear terms won't be negligible but then the $g_{a\gamma}$ constraints will be far too weak to be of interest.

